from taf.collectors.core.templates.dynamic_class_creation import Using
from taf.collectors.core import StartableCollector
from taf.collectors.core.entities.executor import ExecutionError
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TsharkCollector(Using("tool_executor"), Using("file_getter"), StartableCollector):
    """
          To Start , Stop and Collect  tshark logs on given configuration.
    """

    def __init__(self,
                 options=None,
                 tshark_path="tshark",
                 start_timeout=10,
                 stop_timeout=3,
                 target_file_name=None,
                 **kwargs):
        super(TsharkCollector, self).__init__(**kwargs)
        self._log_path = "/tmp/tshark_{name}.pcap".format(name=self._name)
        self._tshark_path = tshark_path
        self._target_file_name = target_file_name if target_file_name \
            else "{name}.pcap".format(name=self._name)
        self._options = " {options}".format(options=options) if options else ""
        self._sudo_prefix = None
        self._stop_timeout = stop_timeout
        self._start_timeout = start_timeout

    def _start(self):
        self._do_start()
        self._wait_for_start_completed()

    def _do_start(self):
        start_command = (
            "touch '{log_path}' ; "
            "'{tshark_path}' -w '{log_path}'{options}").format(
            log_path=self._log_path,
            tshark_path=self._tshark_path,
            options=self._options).encode()
        self._process = self._tool_executor.start(start_command, use_tty=True)

    def _wait_for_start_completed(self):
        stdout_output = self._process.stdout.read_line(timeout=self._start_timeout)
        if b'Capturing on' not in stdout_output:
            if not self._process.is_running:
                stdout_output += self._process.stdout.read()
                exit_status = self._process.exit_status
            else:
                exit_status = None
            raise ExecutionError(
                stdout=stdout_output,
                stderr=None,
                exit_status=exit_status)

    def _stop(self):
        self._process.stdin.write("\x03".encode())
        self._wait_till_process_terminated()

    def _wait_till_process_terminated(self):
        self._process.wait(timeout=self._stop_timeout)

    def _setup(self):
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        self._process_and_file_cleanup()

    def _collect(self, target_dir):
        self._file_getter.get_file(
            source_path=self._log_path,
            target_path="{target_dir}/{target_file_name}".format(
                target_dir=target_dir,
                target_file_name=self._target_file_name))

    def _teardown(self):
        self._process_and_file_cleanup()

    def _process_and_file_cleanup(self):
        try:
            self._tool_executor.execute(
                '{sudo_prefix}pkill -9 -f "{tshark_path} -w {log_path}"'.format(
                    sudo_prefix=self._sudo_prefix,
                    tshark_path=self._tshark_path,
                    log_path=self._log_path).encode())
        except ExecutionError as exception:
            logger.debug("Terminating %r process failed: %r", self._tshark_path, exception)
        self._file_cleanup()

    def _file_cleanup(self):
        self._tool_executor.execute(
            "{sudo_prefix}rm -f '{log_path}'".format(
                sudo_prefix=self._sudo_prefix,
                log_path=self._log_path).encode())
